const URL_SCHEME_REGEX = /^[a-z][a-z\d+.-]*:/i;
const NON_BARE_PREFIXES = ['/', './', '../', '#'];
export const HOST_PROVIDED_PACKAGES = ['react', 'react-dom'];
export const isBareSpecifier = (source) => {
    if (source === '' || source === '.' || source === '..')
        return false;
    if (NON_BARE_PREFIXES.some((prefix) => source.startsWith(prefix)))
        return false;
    return !URL_SCHEME_REGEX.test(source);
};
export const getSpecifierPackageName = (source) => {
    if (!isBareSpecifier(source))
        return undefined;
    const segments = source.split('/');
    if (segments.some((segment) => segment === '.' || segment === '..'))
        return undefined;
    const [first = '', second] = segments;
    if (!first.startsWith('@'))
        return first;
    if (first === '@' || !second)
        return undefined;
    return `${first}/${second}`;
};
export const isHostProvidedSpecifier = (source) => {
    const packageName = getSpecifierPackageName(source);
    return HOST_PROVIDED_PACKAGES.some((name) => name === packageName);
};
